const pageMeta={dashboard:['Dashboard Saya','Pantau aktivitas dan pencapaian hari ini.'],closing:['Input Closing','Catat pencapaian baru dengan cepat.'],ranking:['Ranking Tim','Lihat posisi closing seluruh anggota tim.'],visits:['Dokumentasi Kunjungan','Simpan catatan aktivitas lapangan.'],history:['Riwayat Laporan','Temukan kembali data closing Anda.'],supervisor:['Dashboard Supervisor','Pantau performa dan aktivitas seluruh tim.']};
