const navBase=[['dashboard',icon.home,'Beranda'],['closing',icon.closing,'Closing'],['ranking',icon.ranking,'Ranking'],['visits',icon.visits,'Kunjungan'],['history',icon.history,'Riwayat']];
const $=id=>document.getElementById(id),esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const isoToday=()=>new Date().toLocaleDateString('en-CA'),formatDate=value=>new Intl.DateTimeFormat('id-ID',{day:'numeric',month:'short',year:'numeric'}).format(new Date(`${value}T12:00:00`)),monthLabel=new Intl.DateTimeFormat('id-ID',{month:'long',year:'numeric'}).format(new Date());
