const config=window.TBR_CONFIG||{},configured=config.supabaseUrl&&!config.supabaseUrl.startsWith('YOUR_')&&config.supabasePublishableKey&&!config.supabasePublishableKey.startsWith('YOUR_'),db=configured&&window.supabase?window.supabase.createClient(config.supabaseUrl,config.supabasePublishableKey):null;
let state={role:'staff',page:'dashboard',product:'qris',chartStaff:''},currentUser=null,profile=null,records=[],visits=[],ranking=[];
function showMessage(element,message,isError=false){element.hidden=false;element.textContent=message;element.classList.toggle('error',isError)}
function navItems(){return state.role==='supervisor'?[['supervisor','▦','Overview'],...navBase.slice(1)]:navBase}
function navigate(page){state.page=page;location.hash=page;render();scrollTo({top:0,behavior:'smooth'})}
function renderNav(){const markup=navItems().map(([id,itemIcon,label])=>`<button class="${state.page===id?'active':''}" data-route="${id}"><span class="nav-icon">${itemIcon}</span>${label}</button>`).join('');$('desktopNav').innerHTML=markup;$('mobileNav').innerHTML=markup}
function render(){document.querySelectorAll('.page').forEach(el=>el.classList.toggle('active',el.id===state.page));const meta=pageMeta[state.page]||pageMeta.dashboard;$('pageTitle').textContent=meta[0];$('pageSubtitle').textContent=meta[1];$('roleDesktop').textContent=state.role==='supervisor'?'TBR Supervisor':'TBR Staff';$('profileRole').textContent=state.role==='supervisor'?'TBR Supervisor':'TBR Staff';$('profileName').textContent=profile?.full_name||currentUser?.email||'Staff';$('avatar').textContent=(profile?.full_name||'ST').split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase();const staffOptions=state.role==='supervisor'?ranking:([{userId:currentUser?.id,name:profile?.full_name||'Saya'}]);if(!staffOptions.some(row=>row.userId===state.chartStaff))state.chartStaff=staffOptions[0]?.userId||currentUser?.id;$('staffChartSelect').hidden=state.role!=='supervisor';$('staffChartSelect').innerHTML=staffOptions.map(row=>`<option value="${row.userId}" ${row.userId===state.chartStaff?'selected':''}>${esc(row.name)}</option>`).join('');$('supervisorStaffSelect').innerHTML=staffOptions.map(row=>`<option value="${row.userId}" ${row.userId===state.chartStaff?'selected':''}>${esc(row.name)}</option>`).join('');renderNav();renderProducts();renderLists();renderHistory();renderStaffChart('staffChart',state.chartStaff);renderStaffChart('supervisorStaffChart',state.chartStaff)}
function renderProducts(){const product=products.find(item=>item.id===state.product)||products[0];$('productSelect').innerHTML=products.map(item=>`<option value="${item.id}" ${item.id===product.id?'selected':''}>${item.name}</option>`).join('');$('formTitle').textContent=`Detail ${product.name}`;$('closingFields').innerHTML=`<label>Tanggal closing<input name="date" type="date" value="${isoToday()}" required></label><label>Jumlah closing<input name="qty" type="number" min="1" max="100" value="1" required></label>`+product.fields.map((field,index)=>`<label class="${field[0].startsWith('Nama')?'wide':''}">${field[0]}${field[1]==='select'?`<select name="f${index}" required><option value="">Pilih opsi</option>${field[2].map(value=>`<option>${value}</option>`).join('')}</select>`:`<input name="f${index}" placeholder="${field[2]}" required>`}</label>`).join('')+`<label class="wide">Keterangan tambahan<textarea name="notes" placeholder="Catatan opsional"></textarea></label>`}
function normalizedRanking(){return ranking.length?ranking:[{name:profile?.full_name||'Saya',total:records.reduce((sum,row)=>sum+row.qty,0),isMe:true}]}
function rowMarkup(row,index,max){return `<div class="list-row"><span class="rank-number ${index<3?'top':''}">${index+1}</span><div class="list-body"><strong>${esc(row.name)}</strong><div class="progress"><span style="width:${max?row.total/max*100:0}%"></span></div></div><span class="rank-total">${row.total}</span><small class="rank-unit">closing</small></div>`}
function renderLists(){const ranks=normalizedRanking(),max=ranks[0]?.total||1,total=ranks.reduce((sum,row)=>sum+row.total,0),reporters=ranks.filter(row=>row.total>0).length;$('recentList').innerHTML=records.slice(0,4).map(row=>`<div class="list-row"><span class="list-icon">✓</span><div class="list-body"><strong>${esc(row.product)}</strong><small>${esc(row.detail)} · ${esc(row.date)}</small></div><span class="pill">+${row.qty}</span></div>`).join('')||'<p class="empty">Belum ada aktivitas.</p>';$('topList').innerHTML=ranks.slice(0,3).map((row,index)=>rowMarkup(row,index,max)).join('');$('supervisorTop').innerHTML=ranks.slice(0,4).map((row,index)=>rowMarkup(row,index,max)).join('');$('leaderboard').innerHTML=ranks.map((row,index)=>rowMarkup(row,index,max)).join('');$('heroTotal').textContent=records.filter(row=>row.userId===currentUser.id).reduce((sum,row)=>sum+row.qty,0);$('heroRank').textContent=`#${Math.max(1,ranks.findIndex(row=>row.isMe)+1)}`;$('teamTotal').textContent=total;$('activeStaff').textContent=ranks.length;$('teamTarget').textContent=`${Math.round(total/Math.max(1,ranks.length*40)*100)}%`;$('teamVisits').textContent=visits.length;$('reportingStaff').textContent=`${reporters}/${ranks.length}`;$('teamAverage').textContent=(total/Math.max(1,ranks.length)).toFixed(1);$('barChart').innerHTML=products.map(product=>{const productTotal=records.filter(row=>row.product===product.name).reduce((sum,row)=>sum+row.qty,0);return `<div class="bar-item"><b>${productTotal}</b><span style="height:${Math.min(100,productTotal*5)}%"></span><small>${product.name}</small></div>`}).join('');$('visitGallery').innerHTML=visits.map(visit=>`<div class="visit-card"><div class="visit-image">${visit.photo?`<img src="${visit.photo}" alt="Dokumentasi kunjungan">`:'⌖'}</div><div><strong>Dokumentasi kunjungan</strong><small>${esc(visit.date)}</small><p>${esc(visit.note)}</p></div></div>`).join('')||'<p class="empty">Belum ada dokumentasi.</p>'}
function renderHistory(){const query=($('historySearch').value||'').toLowerCase(),rows=records.filter(row=>(row.product+' '+row.detail).toLowerCase().includes(query));$('historyTable').innerHTML=rows.map(row=>`<tr><td>${esc(row.date)}</td><td><span class="pill">${esc(row.product)}</span></td><td>${esc(row.detail)}</td><td><strong>${row.qty}</strong></td><td><span class="status">Tersimpan</span></td></tr>`).join('')||'<tr><td colspan="5">Data tidak ditemukan.</td></tr>'}
function renderStaffChart(targetId,staffId){const target=$(targetId);if(!target)return;const values=[0,0,0,0,0,0,0];records.filter(row=>row.userId===staffId).forEach(row=>{const day=(new Date(`${row.rawDate}T12:00:00`).getDay()+6)%7;values[day]+=row.qty});const max=Math.max(40,...values),labels=['Sen','Sel','Rab','Kam','Jum','Sab','Min'],points=values.map((value,index)=>`${index*50+10},${150-(value/max*125)}`).join(' ');target.innerHTML=`<div class="chart-y"><span>${max}</span><span>${Math.round(max*.75)}</span><span>${Math.round(max*.5)}</span><span>${Math.round(max*.25)}</span><span>0</span></div><svg viewBox="0 0 320 170" preserveAspectRatio="xMidYMid meet"><polyline class="chart-line" points="${points}"/>${values.map((value,index)=>`<circle cx="${index*50+10}" cy="${150-(value/max*125)}" r="3"/>`).join('')}</svg><div class="chart-x">${labels.map(label=>`<span>${label}</span>`).join('')}</div>`}
function renderClosingBars(){$('closingBars').innerHTML=products.map(product=>{const total=records.filter(row=>row.product===product.name).reduce((sum,row)=>sum+row.qty,0);return `<div class="closing-bar-row"><span>${product.name}</span><div><i style="width:${Math.min(100,total*5)}%;background:#0d9488"></i></div><b>${total}</b></div>`}).join('')}
async function prepareVisitPhoto(file){
  const supported=['image/jpeg','image/png','image/webp'];
  if(!supported.includes(file.type))throw new Error('Gunakan foto berformat JPG, PNG, atau WebP.');
  if(file.size>15*1024*1024)throw new Error('Ukuran foto awal maksimal 15 MB.');
  if(file.size<=1.8*1024*1024)return file;
  const bitmap=await createImageBitmap(file),maxSide=1600,scale=Math.min(1,maxSide/Math.max(bitmap.width,bitmap.height));
  const canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);
  canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();
  let quality=.82,blob;
  do{blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',quality));quality-=.12}while(blob&&blob.size>4.5*1024*1024&&quality>=.34);
  if(!blob)throw new Error('Foto tidak dapat diproses.');
  if(blob.size>5*1024*1024)throw new Error('Foto masih terlalu besar setelah dikompres.');
  return new File([blob],`${file.name.replace(/\.[^.]+$/,'')}.jpg`,{type:'image/jpeg'});
}
async function loadData(){document.body.classList.add('loading');const firstDay=isoToday().slice(0,8)+'01',ownProfile=await db.from('profiles').select('full_name,nip,role,requested_role,area').eq('id',currentUser.id).single();if(ownProfile.error)throw ownProfile.error;profile=ownProfile.data;state.role=profile.role;state.page=state.role==='supervisor'?'supervisor':'dashboard';const [closingResult,visitResult,leaderboardResult]=await Promise.all([db.from('closings').select('id,user_id,closing_date,product,activity,quantity,notes').gte('closing_date',firstDay).order('closing_date',{ascending:false}),db.from('visits').select('id,user_id,visit_date,notes,photo_path').order('visit_date',{ascending:false}).limit(20),db.rpc('monthly_leaderboard',{month_start:firstDay})]);if(closingResult.error)throw closingResult.error;if(visitResult.error)throw visitResult.error;if(leaderboardResult.error)throw leaderboardResult.error;records=closingResult.data.map(row=>({id:row.id,userId:row.user_id,rawDate:row.closing_date,date:formatDate(row.closing_date),product:row.product,detail:[row.activity,row.notes].filter(Boolean).join(' · '),qty:row.quantity}));ranking=leaderboardResult.data.map(row=>({userId:row.user_id,name:row.full_name,total:Number(row.total),isMe:row.user_id===currentUser.id}));visits=await Promise.all(visitResult.data.map(async row=>{let photo='';if(row.photo_path){const signed=await db.storage.from('visit-photos').createSignedUrl(row.photo_path,3600);photo=signed.data?.signedUrl||''}return {date:formatDate(row.visit_date),note:row.notes,photo}}));document.body.classList.remove('loading');render()}
async function handleSession(session){currentUser=session?.user||null;$('authScreen').hidden=Boolean(currentUser);document.querySelector('.app-shell').hidden=!currentUser;$('mobileNav').hidden=!currentUser;if(currentUser)try{await loadData()}catch(error){document.body.classList.remove('loading');showMessage($('loginMessage'),`Gagal memuat data: ${error.message}`,true);$('authScreen').hidden=false}}
function showAuthPanel(panel){const signingIn=panel==='signin';$('loginForm').hidden=!signingIn;$('signupForm').hidden=signingIn;$('signInTab').classList.toggle('active',signingIn);$('signUpTab').classList.toggle('active',!signingIn);$('signInTab').setAttribute('aria-selected',signingIn);$('signUpTab').setAttribute('aria-selected',!signingIn)}
$('signInTab').addEventListener('click',()=>showAuthPanel('signin'));$('signUpTab').addEventListener('click',()=>showAuthPanel('signup'));
$('loginForm').addEventListener('submit',async event=>{event.preventDefault();if(!db)return;const button=event.currentTarget.querySelector('button'),nip=normalizeNip($('loginNip').value);button.disabled=true;showMessage($('loginMessage'),'Memeriksa akun…');const {error}=await db.auth.signInWithPassword({email:nipToEmail(nip),password:$('loginPassword').value});button.disabled=false;if(error)showMessage($('loginMessage'),'NIP atau password tidak valid.',true)});
$('signupForm').addEventListener('submit',async event=>{event.preventDefault();if(!db)return;const button=event.currentTarget.querySelector('button'),nip=normalizeNip($('signupNip').value),fullName=$('signupFullName').value.trim(),requestedRole=$('signupRole').value;button.disabled=true;showMessage($('signupMessage'),'Mendaftarkan akun…');const {data,error}=await db.auth.signUp({email:nipToEmail(nip),password:$('signupPassword').value,options:{data:{nip,full_name:fullName,requested_role:requestedRole}}});button.disabled=false;if(error)return showMessage($('signupMessage'),error.message.includes('already')?'NIP sudah terdaftar.':`Pendaftaran gagal: ${error.message}`,true);event.currentTarget.reset();if(data.session){showMessage($('signupMessage'),requestedRole==='supervisor'?'Akun dibuat. Akses supervisor menunggu persetujuan admin.':'Akun berhasil dibuat.')}else showMessage($('signupMessage'),'Akun dibuat, tetapi konfirmasi email masih aktif di Supabase. Nonaktifkan Confirm email agar login NIP dapat digunakan.',true)});
$('logoutButton').addEventListener('click',()=>db?.auth.signOut());$('productSelect').addEventListener('change',event=>{state.product=event.target.value;renderProducts()});$('staffChartSelect').addEventListener('change',event=>{state.chartStaff=event.target.value;renderStaffChart('staffChart',state.chartStaff);renderStaffChart('supervisorStaffChart',state.chartStaff);$('supervisorStaffSelect').value=state.chartStaff});$('supervisorStaffSelect').addEventListener('change',event=>{state.chartStaff=event.target.value;renderStaffChart('staffChart',state.chartStaff);renderStaffChart('supervisorStaffChart',state.chartStaff);$('staffChartSelect').value=state.chartStaff});
$('closingForm').addEventListener('submit',async event=>{event.preventDefault();const data=new FormData(event.currentTarget),product=products.find(item=>item.id===state.product),activity=product.fields.map((_,index)=>data.get(`f${index}`)).filter(Boolean).join(' · '),{error}=await db.from('closings').insert({user_id:currentUser.id,closing_date:data.get('date'),product:product.name,activity,quantity:Number(data.get('qty')),notes:data.get('notes')||null});if(error)return showMessage($('closingMessage'),`Gagal menyimpan: ${error.message}`,true);showMessage($('closingMessage'),'Closing berhasil disimpan.');await loadData()});
$('visitForm').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('button[type="submit"]'),sourceFile=$('visitPhoto').files[0];button.disabled=true;let photoPath=null;try{showMessage($('visitMessage'),sourceFile?'Memproses dan mengunggah foto…':'Menyimpan dokumentasi…');if(sourceFile){const file=await prepareVisitPhoto(sourceFile);photoPath=`${currentUser.id}/${crypto.randomUUID()}-${file.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;const upload=await db.storage.from('visit-photos').upload(photoPath,file,{contentType:file.type,upsert:false});if(upload.error)throw new Error(`Gagal mengunggah foto: ${upload.error.message}`)}const {error}=await db.from('visits').insert({user_id:currentUser.id,visit_date:$('visitDate').value,notes:$('visitNotes').value||'Dokumentasi aktivitas lapangan',photo_path:photoPath});if(error){if(photoPath)await db.storage.from('visit-photos').remove([photoPath]);throw new Error(`Gagal menyimpan dokumentasi: ${error.message}`)}form.reset();$('visitDate').value=isoToday();showMessage($('visitMessage'),'Dokumentasi dan foto berhasil disimpan.');await loadData()}catch(error){showMessage($('visitMessage'),error.message||'Foto tidak dapat disimpan.',true)}finally{button.disabled=false}});
$('historySearch').addEventListener('input',renderHistory);document.addEventListener('click',event=>{const route=event.target.closest('[data-route]');if(route)return navigate(route.dataset.route);const close=event.target.closest('[data-close]');if(close)$(close.dataset.close).hidden=true;const open=event.target.closest('[data-open]');if(open){$('closingDetail').hidden=false;renderClosingBars()}});document.addEventListener('keydown',event=>{if(event.key==='Escape')$('closingDetail').hidden=true;if((event.key==='Enter'||event.key===' ')&&event.target.matches('[data-open]'))event.target.click()});window.addEventListener('hashchange',()=>{const target=location.hash.slice(1);if(pageMeta[target]){state.page=target;render()}});
$('visitDate').value=isoToday();document.querySelectorAll('[data-current-month]').forEach(el=>el.textContent=monthLabel);$('setupHint').hidden=configured;if(!configured){$('loginForm').querySelector('button').disabled=true;$('signupForm').querySelector('button').disabled=true;$('authScreen').hidden=false;document.querySelector('.app-shell').hidden=true}else{db.auth.onAuthStateChange((_event,session)=>setTimeout(()=>handleSession(session),0));db.auth.getSession().then(({data})=>handleSession(data.session))}
